def dev_help_text():
    lines = ["Developer parameters:",
             "  -m          dump symbol map",
             "  -b          making messages output unbuffered",
             "  -c <file>   process input file as a comment block and produce HTML output",
             "  -d <level>  enable a debug level, such as (multiple invocations of -d are possible):"]
    for s in DEBUG_SPECS:
        lines.append("\t" + s)
    return "\n".join(lines) + "\n"

def out(s):
    sys.stdout.write(s)
def outb(b):
    sys.stdout.buffer.write(b)
def err(s):
    sys.stderr.write(s)

# ---------- file writing with backup ----------
def write_template_file(filename, data_bytes, backup=True):
    """Write data to filename; if exists, rename to .bak first. Returns True on success."""
    if filename == "-":
        outb(data_bytes)
        return True
    try:
        if backup and os.path.lexists(filename):
            bak = filename + ".bak"
            try:
                if os.path.lexists(bak):
                    if os.path.isdir(bak) and not os.path.islink(bak):
                        # remove empty dir? mimic rename replacing
                        try: os.rmdir(bak)
                        except Exception: pass
                    else:
                        os.remove(bak)
            except Exception:
                pass
            try:
                os.rename(filename, bak)
            except Exception:
                # if rename fails (e.g. directory), try still
                pass
        # if filename is a directory, opening will fail
        with open(filename, "wb") as f:
            f.write(data_bytes)
        return True
    except Exception:
        return False

def write_template_file_no_backup_remove(filename, data_bytes):
    return write_template_file(filename, data_bytes, backup=True)

# ---------- config value tokenization ----------
def strip_comment(line):
    in_q = False
    esc = False
    for i,ch in enumerate(line):
        if esc:
            esc = False
            continue
        if ch == "\\" and in_q:
            esc = True
            continue
        if ch == '"':
            in_q = not in_q
            continue
        if ch == "#" and not in_q:
            return line[:i]
    return line

def tokenize_value(raw, tag, lineno, filename, warnings):
    """Return list of token strings (content). Appends warnings for improper quoting."""
    tokens = []
    i = 0
    n = len(raw)
    while i < n:
        while i < n and raw[i] in " \t\r\n":
            i += 1
        if i >= n:
            break
        start = i
        token_chars = []
        improper = False
        token_raw_end = None
        # a token consists of segments until whitespace
        first_segment = True
        while i < n and raw[i] not in " \t\r\n":
            if raw[i] == '"':
                # quoted segment
                j = i + 1
                content = []
                closed = False
                while j < n:
                    cj = raw[j]
                    if cj == "\\" and j + 1 < n:
                        nxt = raw[j+1]
                        if nxt == '"':
                            content.append('"')
                        elif nxt == "n":
                            content.append("\n")
                        elif nxt == "t":
                            content.append("\t")
                        elif nxt == "\\":
                            content.append("\\")
                        else:
                            content.append("\\")
                            content.append(nxt)
                        j += 2
                        continue
                    if cj == '"':
                        closed = True
                        break
                    content.append(cj)
                    j += 1
                if not closed:
                    # improper: token raw is from start to end of whitespace-delimited token (here to end)
                    k = start
                    while k < n and raw[k] not in " \t\r\n":
                        k += 1
                    raw_tok = raw[start:k]
                    warnings.append(f"warning: Invalid value for '{tag}' tag at line {lineno}, file {filename}: Value '{raw_tok}' is not properly quoted\n")
                    # content is raw without quotes
                    tokens.append(raw_tok.replace('"', ""))
                    i = k
                    token_raw_end = k
                    break
                else:
                    # closed at j
                    after = j + 1
                    if first_segment and after < n and raw[after] not in " \t\r\n":
                        # quoted segment at start followed by non-space -> improper whole token
                        k = start
                        while k < n and raw[k] not in " \t\r\n":
                            k += 1
                        raw_tok = raw[start:k]
                        warnings.append(f"warning: Invalid value for '{tag}' tag at line {lineno}, file {filename}: Value '{raw_tok}' is not properly quoted\n")
                        tokens.append(raw_tok.replace('"', ""))
                        i = k
                        break
                    token_chars.append("".join(content))
                    i = after
                    first_segment = False
                    continue
            else:
                # unquoted segment until quote or whitespace
                j = i
                while j < n and raw[j] not in " \t\r\n\"":
                    # handle escaped space: backslash+space keeps both and includes space
                    if raw[j] == "\\" and j + 1 < n and raw[j+1] in " \t":
                        token_chars.append("\\")
                        token_chars.append(raw[j+1])
                        j += 2
                        continue
                    token_chars.append(raw[j])
                    j += 1
                i = j
                first_segment = False
                continue
        else:
            tokens.append("".join(token_chars))
            continue
        # if we broke due to improper, outer while continues
        if token_raw_end is not None or (i > start and tokens and False):
            pass
    return tokens

def needs_quoting(s):
    if s == "":
        return False
    for ch in s:
        if ch in " \t\n\r,\"":
            return True
    return False

def quote_value(s):
    if needs_quoting(s):
        esc = s.replace('"', '\\"')
        # newlines in values: represent as \n ? original converts newline char to actual? Check: values with \n become newline char, serializing writes actual newline? We'll use \n literal? For safety, keep char as is (it will be newline in output)
        # Actually replace newline char with \n? Observed earlier unclear. Keep as actual char except quote escape.
        return '"' + esc + '"'
    return s

def expand_env(s, noenv):
    if noenv:
        return s
    def repl(m):
        return os.environ.get(m.group(1), "")
    return re.sub(r"\$\(([A-Za-z0-9_]+)\)", repl, s)

# ---------- Config class ----------
class ConfigFatal(Exception):
    def __init__(self, msg):
        self.msg = msg

class Config:
    def __init__(self):
        self.meta = meta_by_name()
        self.order = [m["name"] for m in config_meta()]
        self.values = {}   # name -> internal: str, list, bool, int, enum str
        self.raw = {}      # name -> raw representation string for bool/int/enum (as written), or None
        self.raw_enum = {}
        self.warnings = []
        self.include_paths = []
        self.obsolete_fontname = None
        self.obsolete_fontsize = None
        self.obsolete_font_set = False
        for m in config_meta():
            name = m["name"]; typ = m["type"]; draw = m.get("default_raw","")
            self.raw[name] = draw
            if typ == "bool":
                self.values[name] = (draw.strip().upper() in ("YES","TRUE","1"))
            elif typ == "int":
                try: self.values[name] = int(draw.strip())
                except Exception: self.values[name] = 0
            elif typ == "enum":
                self.values[name] = draw.strip()
            elif typ == "list":
                toks = tokenize_value(draw, name, 1, "Doxyfile", [])
                self.values[name] = toks
            else:
                toks = tokenize_value(draw, name, 1, "Doxyfile", [])
                self.values[name] = " ".join(toks)
        self.defaults = {}
        for k,v in self.values.items():
            if isinstance(v, list):
                self.defaults[k] = list(v)
            else:
                self.defaults[k] = v
        self.default_raw = dict(self.raw)

    def get(self, name, default=None):
        return self.values.get(name, default)
    def get_bool(self, name):
        v = self.values.get(name)
        if isinstance(v, bool): return v
        if isinstance(v, str): return v.strip().upper() in ("YES","TRUE","1")
        return bool(v)
    def get_str(self, name):
        v = self.values.get(name, "")
        if isinstance(v, list): return " ".join(v)
        if isinstance(v, bool): return "YES" if v else "NO"
        return str(v)
    def get_list(self, name):
        v = self.values.get(name, [])
        if isinstance(v, list): return v
        if v == "" or v is None: return []
        return [str(v)]
    def get_int(self, name):
        try: return int(self.values.get(name, 0))
        except Exception: return 0

    def parse_file(self, filename, noenv=False):
        if filename == "-":
            data = sys.stdin.buffer.read()
            self.parse_bytes(data, "-", "-", noenv)
        else:
            try:
                data = Path(filename).read_bytes()
            except Exception:
                raise ConfigFatal(f"error: configuration file {filename} not found!\n")
            self.parse_bytes(data, filename, filename, noenv)

    def parse_bytes(self, data, display_name, real_name, noenv=False):
        # decode
        text = None
        # pre-scan encoding
        enc_name = None
        try:
            ascii_text = data.decode("ascii", errors="ignore")
        except Exception:
            ascii_text = ""
        m = re.search(r"^\s*DOXYFILE_ENCODING\s*=\s*([^\s#]+)", ascii_text, re.M)
        if m:
            enc_name = m.group(1).strip().strip('"')
        if enc_name and enc_name.upper() not in ("UTF-8","UTF8"):
            # check codec
            try:
                codecs.lookup(enc_name)
            except Exception:
                raise ConfigFatal(f"error: Error: unsupported character conversion: '{enc_name}'->'UTF-8'\nCheck the 'DOXYFILE_ENCODING' setting in the config file!\nExiting...\n")
            try:
                text = data.decode(enc_name)
            except Exception as e:
                raise ConfigFatal(f"error: Error: failed to translate characters from {enc_name} to UTF-8: Invalid argument\nExiting...\n")
        if text is None:
            # strip BOM if present
            if data.startswith(codecs.BOM_UTF8):
                data2 = data[len(codecs.BOM_UTF8):]
            else:
                data2 = data
            text = data2.decode("utf-8", errors="replace")
        self.parse_text(text, display_name, noenv, base_dir=None)

    def parse_text(self, text, display_name, noenv=False, base_dir=None):
        # join continuations: backslash-newline -> space, keep line number of start
        physical = text.splitlines()
        logical = []  # (lineno, text)
        i = 0
        while i < len(physical):
            start = i
            line = physical[i]
            while line.rstrip("\r").endswith("\\") and i + 1 < len(physical):
                # remove trailing backslash, add space
                line = line.rstrip("\r")[:-1] + " " + physical[i+1]
                i += 1
            logical.append((start+1, line))
            i += 1
        for lineno, raw_line in logical:
            line = strip_comment(raw_line)
            if line.strip() == "":
                continue
            self.parse_line(line, lineno, display_name, noenv, base_dir)

    def parse_line(self, line, lineno, filename, noenv, base_dir):
        pos = 0
        n = len(line)
        while pos < n:
            while pos < n and line[pos] in " \t\r":
                pos += 1
            if pos >= n:
                break
            ch = line[pos]
            # @INCLUDE handling
            if ch == "@":
                m = re.match(r"@(INCLUDE_PATH|INCLUDE)\s*=\s*(.*)", line[pos:])
                if m:
                    kind = m.group(1); rest = m.group(2).strip()
                    if kind == "INCLUDE_PATH":
                        toks = tokenize_value(rest, "@INCLUDE_PATH", lineno, filename, self.warnings)
                        for t in toks:
                            if t not in self.include_paths:
                                self.include_paths.append(t)
                        return
                    else:
                        toks = tokenize_value(rest, "@INCLUDE", lineno, filename, self.warnings)
                        inc_name = toks[0] if toks else ""
                        self.do_include(inc_name, filename, lineno, noenv)
                        return
                else:
                    self.warnings.append(f"warning: ignoring unknown character '@' at line {lineno}, file {filename}\n")
                    pos += 1
                    continue
            if ch.isalpha() or ch == "_":
                m = re.match(r"[A-Za-z0-9_]+", line[pos:])
                word = m.group(0)
                after_word = pos + len(word)
                # lookahead for = or +=
                j = after_word
                while j < n and line[j] in " \t":
                    j += 1
                op = None; op_end = None
                if line.startswith("+=", j):
                    op = "+="; op_end = j+2
                elif j < n and line[j] == "=":
                    op = "="; op_end = j+1
                if op is not None:
                    rest = line[op_end:]
                    self.handle_assignment(word, op, rest, lineno, filename, noenv)
                    return
                else:
                    self.warnings.append(f"warning: ignoring unknown tag '{word}' at line {lineno}, file {filename}\n")
                    pos = after_word
                    continue
            elif ch.isdigit():
                m = re.match(r"[A-Za-z0-9_]+", line[pos:])
                word = m.group(0)
                self.warnings.append(f"warning: ignoring unknown tag '{word}' at line {lineno}, file {filename}\n")
                pos += len(word)
                continue
            else:
                self.warnings.append(f"warning: ignoring unknown character '{ch}' at line {lineno}, file {filename}\n")
                pos += 1
                continue

    def do_include(self, inc_name, from_file, lineno, noenv):
        # search: relative to cwd, relative to directory of from_file, then include_paths
        candidates = []
        candidates.append(Path(inc_name))
        if from_file and from_file != "-":
            candidates.append(Path(from_file).parent / inc_name)
        for p in self.include_paths:
            candidates.append(Path(p) / inc_name)
            if from_file and from_file != "-":
                candidates.append(Path(from_file).parent / p / inc_name)
        found = None
        for c in candidates:
            if c.is_file():
                found = c; break
        if found is None:
            raise ConfigFatal(f"error: @INCLUDE = {inc_name}: not found!\nExiting...\n")
        data = found.read_bytes()
        # decode simply utf-8
        text = data.decode("utf-8", errors="replace")
        if text.startswith("\ufeff"):
            text = text[1:]
        # parse included with its display name as the found path's name as written? Original warnings use file name as included path?
        # Use str(found) if it contains directory, else name. In tests cwd include, found is Path(inc_name).
        disp = str(found)
        # But for warnings original likely uses the included file name as specified? Keep disp as inc candidate string
        self.parse_text(text, disp, noenv)

    def handle_assignment(self, tag, op, rest_raw, lineno, filename, noenv):
        rest_raw_stripped = rest_raw.strip()
        # disabled tags
        if tag in DISABLED_TAGS:
            self.warnings.append(f"warning: Tag '{tag}' at line {lineno} of file '{filename}' belongs to an option that was not enabled at compile time.\n         To avoid this warning please remove this line from your configuration file or upgrade it using \"doxygen -u\", or recompile doxygen with this feature enabled.\n")
            return
        if tag in OBSOLETE_TAGS:
            self.warnings.append(f"warning: Tag '{tag}' at line {lineno} of file '{filename}' has become obsolete.\n         To avoid this warning please remove this line from your configuration file or upgrade it using \"doxygen -u\"\n")
            # parse value tokens without extra quoting warnings (?) Use tokenize
            expanded = expand_env(rest_raw_stripped, noenv)
            toks = tokenize_value(expanded, tag, lineno, filename, self.warnings)
            val_str = " ".join(toks)
            if tag == "HTML_TIMESTAMP":
                b = val_str.strip().upper() in ("YES","TRUE","1")
                self.values["TIMESTAMP"] = "YES" if b else "NO"
                self.raw["TIMESTAMP"] = val_str if val_str else ("YES" if b else "NO")
                # mark raw enum storage
                self.raw_enum["TIMESTAMP"] = self.raw["TIMESTAMP"]
            elif tag == "CLASS_DIAGRAMS":
                b = val_str.strip().upper() in ("YES","TRUE","1")
                if not b and val_str.strip() != "":
                    self.values["CLASS_GRAPH"] = "TEXT"
                    self.raw["CLASS_GRAPH"] = "TEXT"
                    self.warnings.append("warning: Changing CLASS_GRAPH option to TEXT because obsolete option CLASS_DIAGRAM was found and set to NO.\n")
            elif tag == "DOT_FONTNAME":
                self.obsolete_fontname = val_str
                self.obsolete_font_set = True
            elif tag == "DOT_FONTSIZE":
                self.obsolete_fontsize = val_str
                self.obsolete_font_set = True
            # others ignore
            return
        if tag not in self.meta:
            self.warnings.append(f"warning: ignoring unsupported tag '{tag}' at line {lineno}, file {filename}\n")
            return
        meta = self.meta[tag]
        typ = meta["type"]
        if op == "+=" and typ != "list":
            self.warnings.append(f"warning: operator += not supported for '{tag} +='. Ignoring line at line {lineno}, file {filename}\n")
            return
        # value processing
        expanded = expand_env(rest_raw_stripped, noenv)
        toks = tokenize_value(expanded, tag, lineno, filename, self.warnings)
        if typ == "string":
            self.values[tag] = " ".join(toks)
            self.raw[tag] = self.values[tag]
        elif typ == "list":
            if op == "+=":
                cur = list(self.values.get(tag, []))
                cur.extend(toks)
                self.values[tag] = cur
            else:
                self.values[tag] = list(toks)
        elif typ == "bool":
            if expanded.strip() == "":
                return
            arg = " ".join(toks) if toks else expanded.strip()
            low = arg.strip().lower()
            if low in ("yes","true","1"):
                self.values[tag] = True
                self.raw[tag] = arg.strip()
            elif low in ("no","false","0"):
                self.values[tag] = False
                self.raw[tag] = arg.strip()
            else:
                self.warnings.append(f"warning: argument '{arg.strip()}' for option {tag} is not a valid boolean value\nUsing the default: {self.default_raw[tag].strip()}!\n")
                self.values[tag] = self.defaults[tag]
                self.raw[tag] = self.default_raw[tag]
        elif typ == "int":
            if expanded.strip() == "":
                return
            arg = " ".join(toks) if toks else expanded.strip()
            arg = arg.strip()
            rng = meta.get("range") or [None,None]
            try:
                iv = int(arg, 10)
                if rng[0] is not None and (iv < rng[0] or iv > rng[1]):
                    raise ValueError()
                self.values[tag] = iv
                self.raw[tag] = arg
            except Exception:
                if rng[0] is not None:
                    self.warnings.append(f"warning: argument '{arg}' for option {tag} is not a valid number in the range [{rng[0]}..{rng[1]}]!\nUsing the default: {self.defaults[tag]}!\n")
                else:
                    self.warnings.append(f"warning: argument '{arg}' for option {tag} is not a valid number!\nUsing the default: {self.defaults[tag]}!\n")
                self.values[tag] = self.defaults[tag]
                self.raw[tag] = self.default_raw[tag]
        elif typ == "enum":
            if expanded.strip() == "":
                return
            arg = " ".join(toks) if toks else expanded.strip()
            arg = arg.strip()
            vals = meta.get("values", [])
            canon = None
            for v in vals:
                if v.lower() == arg.lower():
                    canon = v; break
            if canon is None:
                self.warnings.append(f"warning: argument '{arg}' for option {tag} is not a valid enum value\nUsing the default: {self.defaults[tag]}!\n")
                self.values[tag] = self.defaults[tag]
                self.raw[tag] = self.default_raw[tag]
            else:
                self.values[tag] = canon
                self.raw[tag] = arg  # preserve raw for update writing
                self.raw_enum[tag] = arg
        else:
            self.values[tag] = " ".join(toks)

    def post_process_dot(self):
        if not self.obsolete_font_set:
            return
        fontname = self.obsolete_fontname if self.obsolete_fontname is not None else "Helvetica"
        fontsize = self.obsolete_fontsize if self.obsolete_fontsize is not None else "10"
        # only if fontname/fontsize set? original runs when either obsolete present
        for tag, name_key, size_key in [("DOT_COMMON_ATTR","fontname","fontsize"),("DOT_EDGE_ATTR","labelfontname","labelfontsize")]:
            cur = self.get_str(tag)
            if cur == "":
                parts = []
            else:
                parts = cur.split(",")
            # transform
            def fmt_val(v):
                if " " in v:
                    return '\\"' + v + '\\"'
                return v
            new_parts = []
            found_name = False; found_size = False
            for part in parts:
                if "=" in part:
                    k, v = part.split("=",1)
                    ks = k.strip()
                    if ks == name_key:
                        new_parts.append(f"{ks}={fmt_val(fontname)}"); found_name = True; continue
                    if ks == size_key:
                        new_parts.append(f"{ks}={fontsize}"); found_size = True; continue
                new_parts.append(part)
            if not found_name:
                new_parts.append(f"{name_key}={fmt_val(fontname)}")
            # fontsize not appended if not found (observed)
            self.values[tag] = ",".join(new_parts)

    # serialization
    def serialize_assignment(self, tag, for_diff=False):
        meta = self.meta[tag]; typ = meta["type"]
        prefix = tag.ljust(23) + "= "
        indent = " " * 25
        if typ == "list":
            items = self.values.get(tag, [])
            if not items:
                return f"{prefix}\n"
            lines = []
            for idx, it in enumerate(items):
                q = quote_value(str(it))
                if idx == 0:
                    line = prefix + q
                else:
                    line = indent + q
                if idx < len(items)-1:
                    line += " \\"
                lines.append(line)
            return "\n".join(lines) + "\n"
        elif typ == "bool":
            raw = self.raw.get(tag, None)
            if raw is None or raw == "":
                raw = "YES" if self.values.get(tag) else "NO"
            # raw may be default_raw with spaces? strip
            return f"{prefix}{str(raw).strip()}\n"
        elif typ == "int":
            raw = self.raw.get(tag, str(self.values.get(tag,"")))
            return f"{prefix}{str(raw).strip()}\n"
        elif typ == "enum":
            if for_diff:
                val = str(self.values.get(tag,""))
            else:
                val = str(self.raw.get(tag, self.values.get(tag,""))).strip()
                if val == "":
                    val = str(self.values.get(tag,""))
            return f"{prefix}{val}\n"
        else:
            val = str(self.values.get(tag,""))
            return f"{prefix}{quote_value(val) if val!='' else ''}\n"

    def is_different(self, tag):
        meta = self.meta[tag]; typ = meta["type"]
        if typ == "bool":
            return bool(self.values.get(tag)) != bool(self.defaults.get(tag))
        if typ == "int":
            try: return int(self.values.get(tag)) != int(self.defaults.get(tag))
            except Exception: return str(self.values.get(tag)) != str(self.defaults.get(tag))
        if typ == "enum":
            return str(self.values.get(tag,"")).lower() != str(self.defaults.get(tag,"")).lower()
        if typ == "list":
            return list(self.values.get(tag,[])) != list(self.defaults.get(tag,[]))
        return str(self.values.get(tag,"")) != str(self.defaults.get(tag,""))

    def diff_text(self):
        self.post_process_dot()
        sb = [f"# Difference with default Doxyfile {VERSION_FULL}\n"]
        for tag in self.order:
            if self.is_different(tag):
                sb.append(self.serialize_assignment(tag, for_diff=True))
        return "".join(sb)

    def template_text(self, short=False):
        self.post_process_dot()
        template = resource_text("config_short.txt" if short else "config_full.txt")
        # replace assignment blocks in template with serialized assignments.
        # Parse template line by line, when line starts with TAG =, replace its block (including continuations) with our serialization (without trailing newline handling)
        lines = template.splitlines(True)  # keep ends
        out_lines = []
        i = 0
        # Need map of serialized lines (no trailing \n in comparison?) serialize returns ending \n
        while i < len(lines):
            line = lines[i]
            m = re.match(r"^([A-Z][A-Z0-9_]*)\s*=", line)
            if m and m.group(1) in self.meta:
                tag = m.group(1)
                # skip continuation lines
                j = i
                while lines[j].rstrip("\r\n").rstrip().endswith("\\") and j + 1 < len(lines):
                    j += 1
                # preserve separation? serialized has newline
                out_lines.append(self.serialize_assignment(tag, for_diff=False))
                i = j + 1
            else:
                out_lines.append(line)
                i += 1
        return "".join(out_lines)

def flush_warnings(cfg):
    for w in cfg.warnings:
        err(w)
    cfg.warnings = []

# ---------- template writers ----------
def do_generate_config(short, filename):
    cfg = Config()  # defaults
    text = cfg.template_text(short=short)
