def do_generate_config(short, filename):
    cfg = Config()  # defaults
    text = cfg.template_text(short=short)
    data = text.encode("utf-8")
    if filename == "-":
        outb(data)
        return 0
    if filename == "":
        err("error: Cannot open file  for writing\n")
        return 1
    # attempt write
    ok = write_template_file(filename, data, backup=True)
    if not ok:
        err(f"error: Cannot open file {filename} for writing\n")
        return 1
    if filename == "Doxyfile":
        msg = f"\n\nConfiguration file '{filename}' created.\n\nNow edit the configuration file and enter\n\n  doxygen\n\nto generate the documentation for your project\n\n"
    else:
        msg = f"\n\nConfiguration file '{filename}' created.\n\nNow edit the configuration file and enter\n\n  doxygen {filename}\n\nto generate the documentation for your project\n\n"
    out(msg)
    return 0

def do_update_config(short, cfg, filename):
    text = cfg.template_text(short=short)
    data = text.encode("utf-8")
    if filename == "-":
        outb(data)
        return 0
    # backup original already? Config file exists; rename to .bak then write
    ok = write_template_file(filename, data, backup=True)
    if not ok:
        err(f"error: Cannot open file {filename} for writing\n")
        return 1
    out(f"\n\nConfiguration file '{filename}' updated.\n\n")
    return 0

