def convert_comment_file(cfg, filename):
    # -c mode: read file, treat as comment block, produce HTML
    try:
        text=Path(filename).read_text(errors="replace")
    except Exception:
        # If file not found, original behavior? It was run after config check, what error?
        err(f"error: file '{filename}' not found or could not be opened\n")
        return 1
    # Strip C comment markers if present
    stripped=text.strip()
    # If it's a block comment, extract inside
    m=re.match(r"^/\*[*!]?\s*(.*?)\s*\*/$", stripped, re.S)
    if m:
        inner=m.group(1)
        # strip leading * per line
        lines=[]
        for l in inner.splitlines():
            s=l.strip()
            if s.startswith("*"): s=s[1:].lstrip()
            lines.append(s)
        stripped="\n".join(lines)
    else:
        # line comments /// etc strip
        lines=[]
        for l in text.splitlines():
            s=l.strip()
            if s.startswith("///") or s.startswith("//!"):
                s=s[3:].lstrip()
            elif s.startswith("//"):
                s=s[2:].lstrip()
            lines.append(s)
        # Only use stripped if original looked like comments? If plain text, use original text
        if any(l.strip().startswith("//") for l in text.splitlines()):
            stripped="\n".join(lines)
        else:
            stripped=text
    doc=parse_doc_block(stripped)
    # For -c, original outputs paragraph HTML from markdown/doc conversion of whole text, not just brief.
    # Use full text conversion: if doc has brief/detail/params etc, render somewhat.
    # Simple cases: "Hello **bold**\n" -> <p>Hello <b>bold</b> </p>\n
    # We'll convert the whole stripped text as markdown-ish paragraphs, removing doxygen commands markers but keeping their text?
    # Remove \brief etc markers
    clean=re.sub(r"[\\@](brief|details)\s+", "", stripped)
    # If there are params, original would render dl - ignore for simple
    html=doc_text_to_html(clean)
    if html:
        out(html)
    return 0

