def main(argv=None):
    args=sys.argv[1:]
    prog=sys.argv[0]
    short_flag=False
    quiet_flag=False
    generate_flag=False
    update_flag=False
    compare_flag=False
    compare_noenv=False
    input_file=None
    convert_file=None
    debug_flags=[]
    dump_map=False
    # state for deferred modes
    i=0
    while i < len(args):
        arg=args[i]
        # long options exact
        if arg=="--help":
            out(help_text()); return 0
        if arg=="--version":
            out(VERSION_FULL+"\n"); return 0
        if arg in ("--Version","--VERSION"):
            out(VERSION_FULL+"\n    with sqlite3 3.42.0.\n"); return 0
        if arg.startswith("--"):
            out(help_text()); err(f'error: Unknown option "{arg}"\n'); return 1
        if arg=="-":
            input_file="-"; break
        if len(arg)>=2 and arg[0]=="-" and (arg[1].isalpha() or arg[1]=="?"):
            opt=arg[1]
            # -x special validation requires exact
            if opt=="x":
                if arg not in ("-x","-x_noenv"):
                    err(f'error: option should be "-x" or "-x_noenv", found: "{arg}".\n'); return 1
                compare_flag=True; compare_noenv=(arg=="-x_noenv"); i+=1; continue
            if opt=="v":
                out(VERSION_FULL+"\n"); return 0
            if opt=="V":
                out(VERSION_FULL+"\n    with sqlite3 3.42.0.\n"); return 0
            if opt in ("h","?"):
                out(help_text()); return 0
            if opt=="g":
                generate_flag=True; i+=1; continue
            if opt=="u":
                update_flag=True; i+=1; continue
            if opt=="s":
                short_flag=True; i+=1; continue
            if opt=="q":
                quiet_flag=True; i+=1; continue
            if opt=="b":
                i+=1; continue
            if opt=="m":
                dump_map=True; i+=1; continue
            if opt=="t":
                err('error: support for option "-t" has not been compiled in (use a debug build or a release build with tracing enabled).\n'); return 1
            if opt=="d":
                # check next
                if i+1>=len(args) or args[i+1]=="" or args[i+1].startswith("-"):
                    out(dev_help_text()); return 0
                spec=args[i+1]
                if spec not in DEBUG_SPECS:
                    out(f'option "-d" has unknown debug specifier: "{spec}".\n'); out(dev_help_text()); return 1
                debug_flags.append(spec); i+=2; continue
            if opt=="c":
                if i+1>=len(args):
                    out('option "-c" is missing the file name to read\n'); out(dev_help_text()); return 1
                convert_file=args[i+1]; i+=2; continue
            if opt=="l":
                filename=args[i+1] if i+1<len(args) else "DoxygenLayout.xml"
                data=resource_bytes("layout.xml")
                if filename=="-":
                    outb(data); return 0
                ok=write_template_file(filename, data, backup=True)
                if not ok:
                    err(f"error: Failed to open file {filename} for writing!\n"); return 0
                return 0
            if opt=="w":
                # format
                if i+1>=len(args):
                    err('error: option "-w" is missing format specifier rtf, html or latex\n'); return 1
                fmt=args[i+1]
                fmt_low=fmt.lower()
                if fmt_low not in ("rtf","html","latex"):
                    err(f'error: Illegal format specifier "{fmt}": should be one of rtf, html or latex\n'); return 1
                if fmt_low=="rtf":
                    if i+2>=len(args):
                        err('error: option "-w rtf" is missing a style sheet file name\n'); return 1
                    sheet=args[i+2]
                    data=resource_bytes("rtf_style.txt")
                    if sheet=="-":
                        outb(data); return 0
                    ok=write_template_file(sheet, data, backup=True)
                    if not ok:
                        err(f"error: error opening RTF style sheet file {sheet}!\n"); return 1
                    return 0
                else:
                    # html/latex need 3 args
                    if i+4>=len(args):  # need i+2,i+3,i+4
                        err(f'error: option "-w {fmt_low}" does not have enough arguments\n'); return 1
                    header_file=args[i+2]; footer_file=args[i+3]; style_file=args[i+4]
                    cfg_for_w=None
                    if i+5<len(args):
                        cfg_file=args[i+5]
                        if not Path(cfg_file).is_file():
                            err(f"error: file '{cfg_file}' not found or could not be opened\nExiting...\n"); return 1
                        # parse config for potential customization (warnings?)
                        cfg_for_w=Config()
                        try:
                            cfg_for_w.parse_file(cfg_file, noenv=False)
                        except ConfigFatal as e:
                            err(e.msg); return 1
                        # flush warnings? Original -w with config maybe prints warnings to stderr. We'll flush.
                        flush_warnings(cfg_for_w)
                    # choose templates
                    if fmt_low=="html":
                        header_data=resource_bytes("html_header.html"); footer_data=resource_bytes("html_footer.html")
                        # CSS may be adjusted by hue - ignore, use default style (identical for default)
                        style_data=resource_bytes("html_style.css")
                        # If config specified hue etc, css still same length? We'll keep default.
                    else:
                        header_data=resource_bytes("latex_header.tex"); footer_data=resource_bytes("latex_footer.tex"); style_data=resource_bytes("latex_style_template.sty")
                    # write in order header, footer, style; '-' to stdout
                    for fname, data in [(header_file,header_data),(footer_file,footer_data),(style_file,style_data)]:
                        if fname=="-":
                            outb(data)
                        else:
                            ok=write_template_file(fname, data, backup=True)
                            if not ok:
                                # what error message for html? Probe unknown; use generic
                                if fmt_low=="html":
                                    err(f"error: error opening HTML file {fname}!\n")
                                else:
                                    err(f"error: error opening LaTeX file {fname}!\n")
                                return 1
                    return 0
            if opt=="e":
                if i+1>=len(args):
                    err('error: option "-e" is missing format specifier rtf.\n'); return 1
                fmt=args[i+1]
                if fmt.lower()!="rtf":
                    err('error: option "-e" has invalid format specifier.\n'); return 1
                if i+2>=len(args):
                    err('error: option "-e rtf" is missing an extensions file name\n'); return 1
                ext_file=args[i+2]
                data=resource_bytes("rtf_ext.txt")
                if ext_file=="-":
                    outb(data); return 0
                # silent on failure
                write_template_file(ext_file, data, backup=True)
                return 0
            if opt=="f":
                if i+1>=len(args):
                    err('error: option "-f" is missing list specifier.\n'); return 1
                lst=args[i+1]
                if lst.lower()!="emoji":
                    err('error: option "-f" has invalid list specifier.\n'); return 1
                if i+2>=len(args):
                    err('error: option "-f emoji" is missing an output file name\n'); return 1
                out_file=args[i+2]
                data=resource_bytes("emoji.txt")
                if out_file=="-":
                    outb(data); return 0
                write_template_file(out_file, data, backup=True)
                return 0
            # unknown alpha
            out(help_text()); err(f'error: Unknown option "-{opt}"\n'); return 1
        else:
            # positional (including -digit, -punct, plain)
            input_file=arg; break
    # after loop
    # generate mode takes precedence
    if generate_flag:
        filename=input_file if input_file is not None else "Doxyfile"
        return do_generate_config(short_flag, filename)
    # helper to load config for update/compare/run with error handling for missing
    def load_config_or_error(noenv=False):
        # returns (cfg, filename) or (None, exitcode) after printing error
        if input_file is None:
            # default Doxyfile must exist unless stdin? input None means no positional
            if not Path("Doxyfile").is_file():
                out(help_text()); err("error: Doxyfile not found and no input file specified!\n"); return None,1
            fname="Doxyfile"
        elif input_file=="-":
            fname="-"
        else:
            if not Path(input_file).is_file():
                out(help_text()); err(f"error: configuration file {input_file} not found!\n"); return None,1
            fname=input_file
        cfg=Config()
        try:
            cfg.parse_file(fname, noenv=noenv)
        except ConfigFatal as e:
            err(e.msg); return None,1
        cfg.post_process_dot()
        return (cfg,fname),0
    if update_flag:
        res,code = load_config_or_error(noenv=False)
        if res is None:
            return code
        cfg,fname=res
        flush_warnings(cfg)
        return do_update_config(short_flag, cfg, fname)
    if compare_flag:
        res,code = load_config_or_error(noenv=compare_noenv)
        if res is None:
            return code
        cfg,fname=res
        # warnings go to stderr before output? Original -x warnings on stderr separate.
        flush_warnings(cfg)
        out(cfg.diff_text())
        return 0
    # normal run or -c
    res,code = load_config_or_error(noenv=False)
    if res is None:
        return code
    cfg,fname=res
    if convert_file is not None:
        flush_warnings(cfg)
        return convert_comment_file(cfg, convert_file)
    # run documentation: run_documentation flushes cfg warnings itself
    return run_documentation(cfg, fname, quiet_flag, dump_map, debug_flags)

if __name__ == "__main__":
    try:
        sys.exit(main())
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        sys.exit(0)
    except ConfigFatal as e:
        err(e.msg); sys.exit(1)

