    run_warnings = []
    # check output formats
    generate_html = cfg.get_bool("GENERATE_HTML")
    generate_latex = cfg.get_bool("GENERATE_LATEX")
    generate_rtf = cfg.get_bool("GENERATE_RTF")
    generate_man = cfg.get_bool("GENERATE_MAN")
    generate_xml = cfg.get_bool("GENERATE_XML")
    generate_docbook = cfg.get_bool("GENERATE_DOCBOOK")
    any_output = generate_html or generate_latex or generate_rtf or generate_man or generate_xml or generate_docbook or cfg.get_bool("GENERATE_SQLITE3")
    if not any_output:
