def main(argv=None):
    args=sys.argv[1:]
    prog=sys.argv[0]
    short_flag=False
    quiet_flag=False
    generate_flag=False
    update_flag=False
    compare_flag=False
    compare_noenv=False
    input_file=None
    convert_file=None
    debug_flags=[]
    dump_map=False
    # state for deferred modes
    i=0
    while i < len(args):
        arg=args[i]
        # long options exact
        if arg=="--help":
            out(help_text()); return 0
        if arg=="--version":
            out(VERSION_FULL+"\n"); return 0
        if arg in ("--Version","--VERSION"):
            out(VERSION_FULL+"\n    with sqlite3 3.42.0.\n"); return 0
        if arg.startswith("--"):
            out(help_text()); err(f'error: Unknown option "{arg}"\n'); return 1
        if arg=="-":
            input_file="-"; break
        if len(arg)>=2 and arg[0]=="-" and (arg[1].isalpha() or arg[1]=="?"):
            opt=arg[1]
            # -x special validation requires exact
            if opt=="x":
                if arg not in ("-x","-x_noenv"):
                    err(f'error: option should be "-x" or "-x_noenv", found: "{arg}".\n'); return 1
                compare_flag=True; compare_noenv=(arg=="-x_noenv"); i+=1; continue
            if opt=="v":
                out(VERSION_FULL+"\n"); return 0
            if opt=="V":
                out(VERSION_FULL+"\n    with sqlite3 3.42.0.\n"); return 0
            if opt in ("h","?"):
                out(help_text()); return 0
            if opt=="g":
                generate_flag=True; i+=1; continue
            if opt=="u":
                update_flag=True; i+=1; continue
            if opt=="s":
                short_flag=True; i+=1; continue
            if opt=="q":
                quiet_flag=True; i+=1; continue
            if opt=="b":
                i+=1; continue
            if opt=="m":
                dump_map=True; i+=1; continue
            if opt=="t":
                err('error: support for option "-t" has not been compiled in (use a debug build or a release build with tracing enabled).\n'); return 1
            if opt=="d":
                # check next
                if i+1>=len(args) or args[i+1]=="" or args[i+1].startswith("-"):
                    out(dev_help_text()); return 0
                spec=args[i+1]
                if spec not in DEBUG_SPECS:
                    out(f'option "-d" has unknown debug specifier: "{spec}".\n'); out(dev_help_text()); return 1
                debug_flags.append(spec); i+=2; continue
            if opt=="c":
                if i+1>=len(args):
                    out('option "-c" is missing the file name to read\n'); out(dev_help_text()); return 1
                convert_file=args[i+1]; i+=2; continue
            if opt=="l":
                filename=args[i+1] if i+1<len(args) else "DoxygenLayout.xml"
                data=resource_bytes("layout.xml")
