                        err(f'error: option "-w {fmt_low}" does not have enough arguments\n'); return 1
                    header_file=args[i+2]; footer_file=args[i+3]; style_file=args[i+4]
                    cfg_for_w=None
                    if i+5<len(args):
                        cfg_file=args[i+5]
                        if not Path(cfg_file).is_file():
                            err(f"error: file '{cfg_file}' not found or could not be opened\nExiting...\n"); return 1
                        # parse config for potential customization (warnings?)
                        cfg_for_w=Config()
                        try:
                            cfg_for_w.parse_file(cfg_file, noenv=False)
                        except ConfigFatal as e:
                            err(e.msg); return 1
