                    if fmt_low=="html":
                        header_data=resource_bytes("html_header.html"); footer_data=resource_bytes("html_footer.html")
                        # CSS may be adjusted by hue - ignore, use default style (identical for default)
                        style_data=resource_bytes("html_style.css")
                        # If config specified hue etc, css still same length? We'll keep default.
                    else:
                        header_data=resource_bytes("latex_header.tex"); footer_data=resource_bytes("latex_footer.tex"); style_data=resource_bytes("latex_style_template.sty")
                    # write in order header, footer, style; '-' to stdout
                    for fname, data in [(header_file,header_data),(footer_file,footer_data),(style_file,style_data)]:
                        if fname=="-":
                            outb(data)
                        else:
                            ok=write_template_file(fname, data, backup=True)
                            if not ok:
                                # what error message for html? Probe unknown; use generic
                                if fmt_low=="html":
                                    err(f"error: error opening HTML file {fname}!\n")
                                else:
                                    err(f"error: error opening LaTeX file {fname}!\n")
                                return 1
                    return 0
            if opt=="e":
                if i+1>=len(args):
                    err('error: option "-e" is missing format specifier rtf.\n'); return 1
                fmt=args[i+1]
                if fmt.lower()!="rtf":
                    err('error: option "-e" has invalid format specifier.\n'); return 1
                if i+2>=len(args):
                    err('error: option "-e rtf" is missing an extensions file name\n'); return 1
                ext_file=args[i+2]
                data=resource_bytes("rtf_ext.txt")
                if ext_file=="-":
                    outb(data); return 0
                # silent on failure
                write_template_file(ext_file, data, backup=True)
                return 0
            if opt=="f":
                if i+1>=len(args):
                    err('error: option "-f" is missing list specifier.\n'); return 1
                lst=args[i+1]
                if lst.lower()!="emoji":
                    err('error: option "-f" has invalid list specifier.\n'); return 1
                if i+2>=len(args):
                    err('error: option "-f emoji" is missing an output file name\n'); return 1
                out_file=args[i+2]
                data=resource_bytes("emoji.txt")
                if out_file=="-":
                    outb(data); return 0
                write_template_file(out_file, data, backup=True)
                return 0
            # unknown alpha
            out(help_text()); err(f'error: Unknown option "-{opt}"\n'); return 1
        else:
            # positional (including -digit, -punct, plain)
            input_file=arg; break
    # after loop
    # generate mode takes precedence
    if generate_flag:
        filename=input_file if input_file is not None else "Doxyfile"
        return do_generate_config(short_flag, filename)
    # helper to load config for update/compare/run with error handling for missing
    def load_config_or_error(noenv=False):
        # returns (cfg, filename) or (None, exitcode) after printing error
        if input_file is None:
            # default Doxyfile must exist unless stdin? input None means no positional
            if not Path("Doxyfile").is_file():
                out(help_text()); err("error: Doxyfile not found and no input file specified!\n"); return None,1
            fname="Doxyfile"
        elif input_file=="-":
            fname="-"
        else:
            if not Path(input_file).is_file():
                out(help_text()); err(f"error: configuration file {input_file} not found!\n"); return None,1
            fname=input_file
        cfg=Config()
        try:
            cfg.parse_file(fname, noenv=noenv)
        except ConfigFatal as e:
            err(e.msg); return None,1
        cfg.post_process_dot()
        return (cfg,fname),0
    if update_flag:
        res,code = load_config_or_error(noenv=False)
        if res is None:
            return code
        cfg,fname=res
        flush_warnings(cfg)
        return do_update_config(short_flag, cfg, fname)
    if compare_flag:
        res,code = load_config_or_error(noenv=compare_noenv)
        if res is None:
            return code
        cfg,fname=res
        # warnings go to stderr before output? Original -x warnings on stderr separate.
        flush_warnings(cfg)
        out(cfg.diff_text())
        return 0
