    res,code = load_config_or_error(noenv=False)
    if res is None:
        return code
    cfg,fname=res
    if convert_file is not None:
        flush_warnings(cfg)
        return convert_comment_file(cfg, convert_file)
    # run documentation: run_documentation flushes cfg warnings itself
    return run_documentation(cfg, fname, quiet_flag, dump_map, debug_flags)

